WITH recent_employees AS (SELECT * FROM employees WHERE is_remote OR salary < 92000), employees_stats AS (SELECT DATE_FORMAT(hire_date, 'yyyy-MM') AS hire_month, job_title, SUM(CASE WHEN level = 'L5' THEN salary ELSE 0 END) AS l5_salary FROM recent_employees GROUP BY DATE_FORMAT(hire_date, 'yyyy-MM'), job_title) SELECT hire_month, job_title FROM employees_stats WHERE l5_salary >= 74 ORDER BY job_title, hire_month
